-- =========================================================================
-- রক্তদাতা (Roktodata) — Supabase Full Seed Data & 100% Write Unlock
-- এই স্ক্রিপ্টটি Supabase SQL Editor-এ রান করলে:
-- ১. আপনার ডেটাবেসের সবগুলো টেবিলে ১০-১৫টি করে রিয়েল ও ভেরিফাইড বাংলা ডেটা যুক্ত হবে।
-- ২. ওয়েব অ্যাপ থেকে রক্তদানের আবেদন, নিবন্ধন ও রেসপন্স রাইট করার অনুমতি ১০০% উন্মুক্ত হবে।
-- =========================================================================

-- ধাপ ১: RLS আনলক ও পারমিশন নিশ্চিতকরণ (যাতে ওয়েব অ্যাপ থেকে কোনো বাধা ছাড়া রাইট করা যায়)
ALTER TABLE public.profiles DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.donor_profiles DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.emergency_requests DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.donor_responses DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.hospitals_and_banks DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.blood_inventory DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.ambulances DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.donation_camps DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.donation_history DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications DISABLE ROW LEVEL SECURITY;

GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;

-- প্রোফাইল আইডি কনস্ট্রেইন্ট শিথিলকরণ (যাতে auth.users ডিপেন্ডেন্সি ছাড়া সরাসরি প্রোফাইল তৈরি ও সিড ডেটা লোড করা যায়)
ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_id_fkey;
ALTER TABLE public.profiles ALTER COLUMN id SET DEFAULT gen_random_uuid();

-- =========================================================================
-- ধাপ ২: ১৫ জন নিবন্ধিত ব্যবহারকারী প্রোফাইল (Profiles)
-- =========================================================================
ON CONFLICT (id) DO UPDATE SET full_name = EXCLUDED.full_name, phone_number = EXCLUDED.phone_number;

-- =========================================================================
-- ধাপ ৩: ১৫ জন সক্রিয় রক্তদাতা প্রোফাইল (Donor Profiles)
-- =========================================================================
ON CONFLICT (id) DO UPDATE SET total_donations = EXCLUDED.total_donations, is_available = EXCLUDED.is_available;

-- =========================================================================
-- ধাপ ৪: ১২টি হাসপাতাল ও ব্লাড ব্যাংক (Hospitals & Blood Banks)
-- =========================================================================
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, address = EXCLUDED.address;

-- =========================================================================
-- ধাপ ৫: রক্তের বর্তমান মজুদ (Blood Inventory)
-- =========================================================================
ON CONFLICT (hospital_id, blood_group) DO UPDATE SET units_available = EXCLUDED.units_available;

-- =========================================================================
