INSERT INTO public.notifications (user_id, category, title, description, is_unread) VALUES
('c0000001-0000-0000-0000-000000000001', 'urgent', 'বগুড়া সদরে জরুরি B+ রক্ত প্রয়োজন', 'শহীদ জিয়াউর রহমান মেডিকেল কলেজ হাসপাতালে জরুরি অপারেশন চলছে।', true),
('c0000001-0000-0000-0000-000000000001', 'badge', 'অভিনন্দন! আপনি "গোল্ডেন ডোনার" ব্যাজ অর্জন করেছেন', '৬ বার সফল রক্তদান সম্পন্ন করায় আপনাকে সম্মানসূচক ব্যাজ দেওয়া হলো।', true),
('c0000001-0000-0000-0000-000000000002', 'camp', 'আসন্ন সন্ধানী রক্তদান ক্যাম্প', 'আগামী ২৪ অক্টোবর শজিমেক অডিটোরিয়ামে রক্তদান ক্যাম্প অনুষ্ঠিত হবে।', false),
('c0000001-0000-0000-0000-000000000003', 'match', 'আপনার রক্তদানে একজন মুমূর্ষু রোগী সুস্থ হয়েছেন', 'মানবিক সহায়তার জন্য ধন্যবাদ। রোগীর পরিবার কৃতজ্ঞতা প্রকাশ করেছে।', false);
